local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local UITalentMaterialGetRewardNode = "Game.UI.FightReady.UITalent.UITalentMaterialGetRewards.UITalentMaterialGetRewardNode"
local talentQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TalentQuestComponent)
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule

---@class UITalentMaterialGetRewardsDialog
local UITalentMaterialGetRewardsDialog = Class("UITalentMaterialGetRewardsDialog")

function UITalentMaterialGetRewardsDialog:__init() 
    self._curCopyId = 0     --当前的副本id
    self._timeDown = nil
end

function UITalentMaterialGetRewardsDialog:__delete()
    self._curCopyId = 0     --当前的副本id
    self._timeDown = nil
end

function UITalentMaterialGetRewardsDialog:Awake()
    --SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnDetails))
    SetButtonAction(self.controller.gameObject, Bind(self, self.OnBtnClose))
    --SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnDrawReward))
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))

    KTool.SetActive(self.ActivityDetails, talentQuestComponent:GetActiveCloseTime() > 0)

    local argument = self.controller.Argument.parameters
    if not argument then
        return
    end

    self._curCopyId = checkNumber(argument.copyId)    
    if self._curCopyId == 0 then
        return
    end

    self:FillSelf()
end

function UITalentMaterialGetRewardsDialog:FillSelf()
    self:FillRewards()
    self:StartTimeDown()

    local num = QuestConfMgr:GetInstance():GetTalentNotPassRewardProp()
    CfUtils.FillText(self.TxtInstructions, localize("完成课程前选择放弃仅能获得_num_%累计奖励", {_num_ = checkInt(num * 100)}))
end

function UITalentMaterialGetRewardsDialog:StartTimeDown()
    self:ClearTimeDown()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        KTool.SetActive(self.ActivityDetails, talentQuestComponent:GetActiveCloseTime() > 0)
    end, CountDownTime, false, true)
end

function UITalentMaterialGetRewardsDialog:ClearTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
end

function UITalentMaterialGetRewardsDialog:FillRewards()
    local t = QuestConfMgr:GetInstance():GetTalentQuestIdsByCopyId(self._curCopyId)
    if not t then
        return
    end

    for k, v in pairs(t) do
        local go = self.LayoutGroup.transform:Find("CheckpointItem"..k)
        self:FillReward(go, v)
    end
end

function UITalentMaterialGetRewardsDialog:FillReward(go, questId)
    if not go or not questId then
        return
    end

    local scr = CfUtils.GetLuaScr(go, UITalentMaterialGetRewardNode)
    if scr then
        scr:Refresh(questId)
    end
end 

--领取奖励冰退出
function UITalentMaterialGetRewardsDialog:OnBtnDrawReward()
    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(QuestConfMgr:GetInstance():GetTalentRewardId())
    vo.goodsId = vo.refId
    local outputNum = talentQuestComponent:GetCurCopyRewardOutPut()
    vo.forceText = outputNum
    local t = {
        [1] = vo
    }
    GameUtils.SecondConfirm(localize("是否领取奖励并退出"), function()
        talentQuestComponent:DrawRewardReq(function()
            self:OnBtnClose()
        end)
    end, nil, localize("当前累计奖励为x"..talentQuestComponent:GetCurCopyRewardOutPut()), 4, t, true)
end

--活动信息
function UITalentMaterialGetRewardsDialog:OnBtnDetails()
    if self._isShowActivityInfo then
        self._isShowActivityInfo = false
    else
        self._isShowActivityInfo = true
    end 
    KTool.SetActive(self.ActivityInfo, self._isShowActivityInfo)
end 

function UITalentMaterialGetRewardsDialog:OnBtnClose()
    --UIModule.CloseDialog(self.controller)
    UIModule.BackDialog()
end

function UITalentMaterialGetRewardsDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end))
    return coWait
end

function UITalentMaterialGetRewardsDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:ClearTimeDown()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UITalentMaterialGetRewardsDialog
